INSERT INTO _cex_wave_f_profiles_0101 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'ascendex', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:ascendex","type":"cex","slug":"ascendex","name":"AscendEX","aliases":["BitMax","AscendEX Exchange"]},"classification":{"subtype":"ceased custodial multi-product exchange with unresolved withdrawals","tags":["custodial","spot","derivatives","lending","staking","ceased","exchange-token"],"chains":[],"jurisdictions":["global","European Union"]},"status":{"operating_state":"ceased_operations_manual_withdrawal_review","as_of":"2026-08-03","claim_ids":["claim:ascendex:status"]},"outcome":{"label":"unresolved_wind_down_after_authorization_and_operating_constraints","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:ascendex:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"AscendEX, previously called BitMax, was a custodial centralized exchange offering spot markets, leveraged products, futures, staking and lending-like services. Customers relied on the venue to hold balances and process withdrawals. It also issued ASD, a utility token tied to platform benefits. Since July 1, 2026 the trading business has been closed and only limited offboarding functions remain.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:what_it_is:1","claim:ascendex:section:what_it_is:2","claim:ascendex:section:what_it_is:3"]},"what_happened":{"body":"AscendEX stopped all crypto-asset services on July 1, 2026. Its July 6 notice said it lacked authorization under the EU Markets in Crypto-Assets regime and also cited broader regulatory, financial and operational considerations. Automated withdrawals were paused and every request moved to manual review, with no assurance on timing or amount. No reviewed source confirms a bankruptcy filing.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:what_happened:1","claim:ascendex:section:what_happened:2","claim:ascendex:section:what_happened:3"]},"why_this_outcome":{"body":"The clearest documented constraint was authorization: the maximum MiCA transition period ended July 1 and AscendEX said it did not hold the required approval. But the company expressly named financial and operational factors too, then adopted a withdrawal process that allowed delays or non-processing. That combination points to a broader wind-down problem whose balance-sheet cause remains undisclosed, not a simple compliance migration.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:why_this_outcome:1","claim:ascendex:section:why_this_outcome:2","claim:ascendex:section:why_this_outcome:3"]},"strategic_choices":{"body":"AscendEX chose a broad product stack spanning spot, futures, leveraged tokens, staking and lending, then tied fee benefits and other services to ASD holdings. That increased the number of products and customer obligations that had to be shut down at once. Management also waited until after the July 1 effective cessation to publish its detailed retail notice on July 6. The record does not show when licensing or narrower-market alternatives were rejected.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:strategic_choices:1","claim:ascendex:section:strategic_choices:2","claim:ascendex:section:strategic_choices:3"]},"operating_model":{"body":"Users deposited assets into accounts controlled by AscendEX, traded through venue-managed markets and relied on the operator for withdrawals. Futures used multi-asset collateral, while trading fees varied with volume and ASD holdings. This model combined custody, leverage and token incentives inside one operator. The reviewed record provides no audited final balance sheet, customer-liability ledger or withdrawal service level for the wind-down.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:operating_model:1","claim:ascendex:section:operating_model:2","claim:ascendex:section:operating_model:3"]},"token_and_value_capture":{"body":"ASD was marketed as AscendEX’s utility token for platform services and fee advantages. Consumed ASD could be represented as ASDS, which the operator said was non-tradable and could not be converted back. That design linked token usefulness to a functioning venue. Once services stopped, the main disclosed utility disappeared, but the record does not establish a redemption right, residual claim, treasury backing or final treatment for ASD holders.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:token_and_value_capture:1","claim:ascendex:section:token_and_value_capture:2","claim:ascendex:section:token_and_value_capture:3"]},"counterfactual":{"body":"Earlier licensing disclosure, a narrower product or regional footprint, and a published asset-liability reconciliation could have reduced the shock and information gap. They cannot be claimed as cures because AscendEX says financial and operational considerations were also involved. The decisive counterfactual is whether a licensed, solvent core exchange existed outside the affected services. The company has not published the numbers needed to test that question.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:counterfactual:1","claim:ascendex:section:counterfactual:2","claim:ascendex:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Customer risk is concentrated in manual withdrawals: requests may be delayed, require more documents or remain unprocessed, while the operator gives no timing or payout assurance. Legal status is also unresolved because the notice mentions possible insolvency-related constraints without announcing a proceeding. The unsupported legacy claims about a $240 million reserve movement should not be treated as fact. The missing facts are liabilities, reserves and completed payouts.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:risks_and_unknowns:1","claim:ascendex:section:risks_and_unknowns:2","claim:ascendex:section:risks_and_unknowns:3"]},"lifecycle":{"body":"AscendEX launched as BitMax, expanded into a broad custodial trading and yield platform, rebranded, and used ASD as an exchange-linked utility asset. Its active lifecycle ended on July 1, 2026 when services stopped. The current phase is offboarding under manual withdrawal review, not normal operation and not yet a completed insolvency estate. The final lifecycle call depends on payouts and any later administrator or court process.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:lifecycle:1","claim:ascendex:section:lifecycle:2","claim:ascendex:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch for a verified withdrawal completion report, audited assets and liabilities, a regulator or court filing, and clear treatment of ASD. Successful offboarding would mean customers receive reconciled balances and the platform closes without a formal shortfall. A worse outcome would be persistent unprocessed requests or an insolvency proceeding. Until primary evidence resolves those points, the accurate label is ceased operations with unresolved customer offboarding.","as_of":"2026-08-03","claim_ids":["claim:ascendex:section:outlook_and_watch:1","claim:ascendex:section:outlook_and_watch:2","claim:ascendex:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:ascendex:bitmax-era","type":"launch","date":"2018-08-01","description":"The venue launched under the BitMax brand in 2018.","claim_ids":["claim:ascendex:event:bitmax-era"]},{"id":"event:ascendex:asd-rebrand","type":"token","date":"2021-03-22","description":"BitMax rebranded as AscendEX and the exchange token ticker changed from BTMX to ASD.","claim_ids":["claim:ascendex:event:asd-rebrand"]},{"id":"event:ascendex:cessation","type":"closure","date":"2026-07-01","description":"AscendEX ceased crypto-asset services.","claim_ids":["claim:ascendex:event:cessation"]},{"id":"event:ascendex:manual-review","type":"withdrawal_control","date":"2026-07-06","description":"Automated withdrawals were paused and requests moved to manual review.","claim_ids":["claim:ascendex:event:manual-review"]}],"sources":[{"id":"source:ascendex:cessation","title":"Cessation of operations and processing of withdrawals","url":"https://ascendex.com/en/support/articles/138693","publisher":"AscendEX","published_at":"2026-07-06","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Operator notice confirming the July 1 cessation, lack of MiCA authorization, service shutdown and manual withdrawal review.","direct_http_status":404,"access_method":"indexed_browser_snapshot"},{"id":"source:ascendex:mica","title":"Regulation (EU) 2023/1114 on markets in crypto-assets","url":"https://eur-lex.europa.eu/eli/reg/2023/1114/oj","publisher":"European Union","published_at":"2023-05-31","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Articles 59 and 143 governing authorization and the July 1, 2026 end of the maximum transition period.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:ascendex:asd","title":"What is ASD","url":"https://ascendex.com/ko/support/articles/36308","publisher":"AscendEX","published_at":"2019-11-06","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Operator description of ASD utility, holder benefits and supply mechanics.","direct_http_status":404,"access_method":"indexed_browser_snapshot"},{"id":"source:ascendex:asds","title":"What is ASDS","url":"https://ascendex.com/en/support/articles/36312","publisher":"AscendEX","published_at":"2019-11-06","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Operator explanation that ASDS records consumed ASD and cannot be traded or converted back.","direct_http_status":404,"access_method":"indexed_browser_snapshot"},{"id":"source:ascendex:futures","title":"Margin and leverage","url":"https://ascendex.com/en/support/articles/62084","publisher":"AscendEX","published_at":"2021-12-10","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Operator description of the futures multi-asset collateral and margin model.","direct_http_status":404,"access_method":"indexed_browser_snapshot"},{"id":"source:ascendex:fees","title":"AscendEX VIP fee and rebate structure","url":"https://ascendex.com/en/support/articles/1699","publisher":"AscendEX","published_at":"2021-10-18","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Operator description of trading-volume and ASD-holding fee tiers.","direct_http_status":404,"access_method":"indexed_browser_snapshot"},{"id":"source:ascendex:cryptoslate","title":"AscendEX shuts down after MiCA miss and warns some withdrawals may not be processed","url":"https://cryptoslate.com/ascendex-shuts-down-after-mica-miss-and-warns-some-withdrawals-may-not-be-processed/","publisher":"CryptoSlate","published_at":"2026-07-07","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent coverage of the operator notice and unresolved withdrawal process.","direct_http_status":403,"access_method":"indexed_browser_snapshot"},{"id":"source:ascendex:crowdfund","title":"Crypto exchange AscendEX halts all operations","url":"https://www.crowdfundinsider.com/2026/07/290550-crypto-exchange-ascendex-halts-all-operations-offers-no-guarantees-on-customer-fund-withdrawals/","publisher":"Crowdfund Insider","published_at":"2026-07-07","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"C","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent account of cessation, withdrawal uncertainty and the absence of a confirmed bankruptcy filing.","direct_http_status":200,"access_method":"direct_http"}],"claims":[{"id":"claim:ascendex:status","field_path":"status.operating_state","assertion":"AscendEX ceased crypto-asset services on July 1, 2026 and limited account access to offboarding functions, with withdrawals under manual review.","value":"ceased_operations_manual_withdrawal_review","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation","source:ascendex:cryptoslate","source:ascendex:crowdfund"],"evidence_locator":"Dated operator notice corroborated by independent coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:outcome","field_path":"outcome.label","assertion":"AscendEX is an unresolved wind-down rather than a confirmed bankruptcy or completed customer-loss event.","value":"unresolved_wind_down_after_authorization_and_operating_constraints","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:ascendex:cessation","source:ascendex:cryptoslate","source:ascendex:crowdfund"],"evidence_locator":"The operator disclosed cessation and possible legal or insolvency constraints but no formal insolvency proceeding or final recovery result.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"AscendEX operated a custodial multi-product crypto venue.","value":"AscendEX operated a custodial multi-product crypto venue.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation","source:ascendex:futures"],"evidence_locator":"Operator product and closure records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"ASD was a venue utility token with platform benefits.","value":"ASD was a venue utility token with platform benefits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:asd","source:ascendex:fees"],"evidence_locator":"Operator token and fee records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Only limited offboarding access remained after service cessation.","value":"Only limited offboarding access remained after service cessation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation"],"evidence_locator":"Section one of the operator notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"AscendEX ceased operations effective July 1, 2026.","value":"AscendEX ceased operations effective July 1, 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation"],"evidence_locator":"Dated operator notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"The operator lacked MiCA authorization and cited additional financial and operational considerations.","value":"The operator lacked MiCA authorization and cited additional financial and operational considerations.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation","source:ascendex:mica"],"evidence_locator":"Operator explanation and EU authorization rule.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"No reviewed source confirms a bankruptcy filing.","value":"No reviewed source confirms a bankruptcy filing.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation","source:ascendex:crowdfund"],"evidence_locator":"Operator wording and independent status report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"The MiCA transition period could run no later than July 1, 2026.","value":"The MiCA transition period could run no later than July 1, 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:mica"],"evidence_locator":"Article 143.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"AscendEX said it did not hold authorization under MiCA.","value":"AscendEX said it did not hold authorization under MiCA.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation"],"evidence_locator":"Operator causal statement.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"The financial and operational contribution to the closure remains unquantified.","value":"The financial and operational contribution to the closure remains unquantified.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation"],"evidence_locator":"The operator listed factors but published no supporting accounts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"AscendEX operated multiple trading and yield products.","value":"AscendEX operated multiple trading and yield products.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation","source:ascendex:futures"],"evidence_locator":"Service list and futures documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"ASD holdings were used in fee tiers and platform benefits.","value":"ASD holdings were used in fee tiers and platform benefits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:asd","source:ascendex:fees"],"evidence_locator":"Operator token mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"The timing and rejection of licensing or retrenchment alternatives are not published.","value":"The timing and rejection of licensing or retrenchment alternatives are not published.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation","source:ascendex:mica"],"evidence_locator":"Disclosure gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"AscendEX controlled service access and withdrawal processing.","value":"AscendEX controlled service access and withdrawal processing.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation"],"evidence_locator":"Offboarding and review rules.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Futures used multi-asset collateral and venue risk controls.","value":"Futures used multi-asset collateral and venue risk controls.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:futures"],"evidence_locator":"Operator futures documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"No audited closing balance sheet or withdrawal service level was found.","value":"No audited closing balance sheet or withdrawal service level was found.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation","source:ascendex:cryptoslate"],"evidence_locator":"Disclosure gap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"ASD supplied platform utility and fee benefits.","value":"ASD supplied platform utility and fee benefits.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:asd","source:ascendex:fees"],"evidence_locator":"Operator token and fee pages.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"ASDS was non-tradable and conversion from ASD was irreversible.","value":"ASDS was non-tradable and conversion from ASD was irreversible.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:asds"],"evidence_locator":"Operator ASDS explanation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"No residual redemption or estate right for ASD is established.","value":"No residual redemption or estate right for ASD is established.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation","source:ascendex:asd"],"evidence_locator":"Closure notice and token page do not create one.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Earlier authorization or retrenchment could have reduced regulatory exposure.","value":"Earlier authorization or retrenchment could have reduced regulatory exposure.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:ascendex:mica","source:ascendex:cessation"],"evidence_locator":"Analyst counterfactual grounded in the deadline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"A balance-sheet reconciliation would reduce withdrawal uncertainty.","value":"A balance-sheet reconciliation would reduce withdrawal uncertainty.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:ascendex:cessation"],"evidence_locator":"Analyst counterfactual grounded in missing liability data.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"Whether a viable narrower business existed is unknown.","value":"Whether a viable narrower business existed is unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation"],"evidence_locator":"No segment economics were disclosed.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"All withdrawal requests were subject to manual review from July 6.","value":"All withdrawal requests were subject to manual review from July 6.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation"],"evidence_locator":"Operator withdrawal section.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The notice did not guarantee timing or