inal recovery phase remains unresolved.","value":"The final recovery phase remains unresolved.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation","source:ascendex:crowdfund"],"evidence_locator":"No completion or estate outcome is reported.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Withdrawal completion is the main near-term outcome signal.","value":"Withdrawal completion is the main near-term outcome signal.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:ascendex:cessation"],"evidence_locator":"Published wind-down process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"A court, regulator or audited balance-sheet record could change the classification.","value":"A court, regulator or audited balance-sheet record could change the classification.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:ascendex:cessation","source:ascendex:mica"],"evidence_locator":"Specified falsification evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Final customer recovery and ASD treatment remain unknown.","value":"Final customer recovery and ASD treatment remain unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:ascendex:cessation","source:ascendex:asd"],"evidence_locator":"No final distribution record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:event:bitmax-era","field_path":"events[event:ascendex:bitmax-era]","assertion":"The venue launched under the BitMax brand in 2018.","value":"2018-08-01","as_of":"2018-08-01","confidence":"high","kind":"fact","source_ids":["source:ascendex:asd"],"evidence_locator":"Historical operator token context; month-level date.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:event:asd-rebrand","field_path":"events[event:ascendex:asd-rebrand]","assertion":"BitMax rebranded as AscendEX and the exchange token ticker changed from BTMX to ASD.","value":"2021-03-22","as_of":"2021-03-22","confidence":"high","kind":"fact","source_ids":["source:ascendex:asd","source:ascendex:fees"],"evidence_locator":"Operator historical materials.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:event:cessation","field_path":"events[event:ascendex:cessation]","assertion":"AscendEX ceased crypto-asset services.","value":"2026-07-01","as_of":"2026-07-01","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation"],"evidence_locator":"Dated operator notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:ascendex:event:manual-review","field_path":"events[event:ascendex:manual-review]","assertion":"Automated withdrawals were paused and requests moved to manual review.","value":"2026-07-06","as_of":"2026-07-06","confidence":"high","kind":"fact","source_ids":["source:ascendex:cessation","source:ascendex:cryptoslate"],"evidence_locator":"Operator notice and independent coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:00:00Z","next_review_at":"2026-08-10T22:00:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Audited asset-liability reconciliation","Withdrawal completion statistics","Formal insolvency status","Final ASD treatment"]},"extensions":{"legacy_origin":"dead_exchanges","identity_boundary":"This profile covers the AscendEX/BitMax custodial venue and its offboarding process. ASD is the venue utility token; ASDS is a non-tradable accounting representation of consumed ASD. A lack of MiCA authorization explains the EU deadline but does not by itself prove insolvency or quantify customer losses.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, custody liabilities and tokens are kept separate.","The legacy $240 million reserve-drop and liquidity-injection story is excluded because the reviewed primary record does not substantiate it.","The operator names regulatory, financial and operational considerations together, so this report does not reduce the closure to MiCA alone."],"explicit_unknowns":["Total customer liabilities and liquid reserves","Number and value of withdrawals completed or rejected","Whether formal insolvency proceedings will begin","Post-closure rights and utility of ASD"]}}', '{"kind":"cex","slug":"ascendex","lifecycle":"dead","operating_model":"Ceased custodial multi-product exchange with customer withdrawals under manual review.","product_cohort":"centralized_multi_product_exchange","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"launched","token_symbol":"ASD","token_launch_date":"2019-11-06","token_launch_timing":"post_product","token_strategy":"exchange_utility_and_fee_benefits","token_source_url":"https://ascendex.com/ko/support/articles/36308","metric_type":"withdrawal_latency","metric_unit":"unknown","metric_window":"manual_review_unresolved","metric_as_of":"2026-08-03","metric_observed_at":"2026-08-03T22:00:00Z","comparability_key":"cex|centralized_multi_product_exchange|withdrawal_latency|unknown|manual_review_unresolved","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"This profile covers the AscendEX/BitMax custodial venue and its offboarding process. ASD is the venue utility token; ASDS is a non-tradable accounting representation of consumed ASD. A lack of MiCA authorization explains the EU deadline but does not by itself prove insolvency or quantify customer losses.","source_count":8},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_f_profiles_0101 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'blockfi', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:blockfi","type":"cex","slug":"blockfi","name":"BlockFi","aliases":["BlockFi Inc.","BlockFi Lending LLC"]},"classification":{"subtype":"failed crypto lender and broker with plan-administered distributions","tags":["lender","earn","broker","custodial","chapter-11","wind-down","no-venue-token"],"chains":[],"jurisdictions":["United States","Bermuda"]},"status":{"operating_state":"closed_plan_administration_and_distributions","as_of":"2026-08-03","claim_ids":["claim:blockfi:status"]},"outcome":{"label":"failed_lender_in_wind_down_with_dollarized_claim_recovery","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:blockfi:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"BlockFi was a custodial crypto lender and broker, not a normal centralized order-book exchange. Customers could place assets into interest accounts, borrow against collateral, hold wallet assets and use a trading interface. BlockFi then lent or invested pooled assets to earn a spread. Today the products are closed; a plan administrator and claims agents manage recoveries and distributions for several legally distinct debtor entities.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:what_it_is:1","claim:blockfi:section:what_it_is:2","claim:blockfi:section:what_it_is:3"]},"what_happened":{"body":"BlockFi settled federal and state registration cases for a combined $100 million in February 2022 and stopped offering new U.S. interest accounts. Later that year it relied on financing connected to FTX while retaining exposures to FTX, Alameda and other failed counterparties. After FTX collapsed, BlockFi paused withdrawals and filed Chapter 11 on November 28. Its confirmed plan became effective in October 2023 and shifted the business into recovery and distribution.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:what_happened:1","claim:blockfi:section:what_happened:2","claim:blockfi:section:what_happened:3"]},"why_this_outcome":{"body":"BlockFi funded customer yield by taking credit and investment risk outside customer wallets. That made repayment dependent on borrower quality, collateral and the survival of large crypto counterparties. The SEC had already found its public loan-risk statement misleading, and the 2022 market collapse exposed concentrated counterparty risk. FTX’s failure was the immediate trigger, but the deeper weakness was a maturity and credit model that could not meet customer withdrawals after counterparties failed.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:why_this_outcome:1","claim:blockfi:section:why_this_outcome:2","claim:blockfi:section:why_this_outcome:3"]},"strategic_choices":{"body":"BlockFi chose to combine custody, retail yield, institutional lending, collateralized loans and brokerage in one brand. It pursued continued U.S. yield distribution through a proposed registered product after the SEC settlement, while also accepting financing and exposure linked to FTX during the credit crisis. Those decisions preserved growth options but concentrated funding and recovery risk. The plan later chose liquidation and claims recovery rather than trying to relaunch the consumer platform.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:strategic_choices:1","claim:blockfi:section:strategic_choices:2","claim:blockfi:section:strategic_choices:3"]},"operating_model":{"body":"Interest-account customers transferred crypto to BlockFi in exchange for variable monthly yield. BlockFi pooled those assets, made institutional loans and held other investments; wallet, loan-collateral and interest-account customers had different legal positions. Trading was a brokerage feature inside that platform, not the central matching business used by a conventional exchange. Once the platform paused, account balances became entity- and product-specific claims administered under the plan.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:operating_model:1","claim:blockfi:section:operating_model:2","claim:blockfi:section:operating_model:3"]},"token_and_value_capture":{"body":"BlockFi did not issue a venue token identified in the reviewed court and regulatory record. Value was meant to accrue to the private company through the spread between what it earned on loans and investments and what it paid to interest-account customers, plus product fees. Customers therefore held contractual account or wallet claims rather than a liquid governance token. In bankruptcy, recovery followed those claims and legal entities, not token-holder rights.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:token_and_value_capture:1","claim:blockfi:section:token_and_value_capture:2","claim:blockfi:section:token_and_value_capture:3"]},"counterfactual":{"body":"Lower counterparty concentration, stronger liquidity reserves and transparent borrower-level stress testing could have reduced the chance that one market failure froze the platform. Segregating wallet assets from yield products and limiting new risk after the SEC settlement would also have narrowed customer confusion and exposure. None of those controls guarantees survival in a system-wide crash. The test is whether BlockFi could have met withdrawals without recoveries from failed borrowers; the filing shows it could not.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:counterfactual:1","claim:blockfi:section:counterfactual:2","claim:blockfi:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The exchange-like app is gone, but creditor administration is not fully finished. Remaining risks include failed identity checks, jurisdiction-specific distribution routes, disputed claims, estate costs and scams impersonating the administrator. The headline 100% figure is limited to eligible allowed dollar claims; it does not compensate for later crypto appreciation or promise every claimant has been paid. A separate 2025 securities settlement must not be added to Chapter 11 recovery as if it were the same pool.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:risks_and_unknowns:1","claim:blockfi:section:risks_and_unknowns:2","claim:blockfi:section:risks_and_unknowns:3"]},"lifecycle":{"body":"BlockFi grew from a 2017 startup into a large crypto lender, added wallet, credit and trading products, and was forced to change its U.S. interest-account offering after the 2022 SEC settlement. The credit crisis and FTX collapse then caused a withdrawal pause and Chapter 11 filing. A confirmed plan took effect in 2023, the web platform closed, and distributions advanced in 2024 and 2025. This is a failed operating business with an unusually strong dollar-claim recovery, not a relaunch.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:lifecycle:1","claim:blockfi:section:lifecycle:2","claim:blockfi:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch the Kroll and court pages for final distributions, unclaimed property, contested claims and estate closure. Also track the separate securities-settlement allocation without combining it with bankruptcy payments. The operating outlook is settled: BlockFi is not returning as a lender or exchange. The remaining analytical question is final claimant recovery after administrative frictions and whether allowed-dollar payments matched the economic value customers expected from their original crypto.","as_of":"2026-08-03","claim_ids":["claim:blockfi:section:outlook_and_watch:1","claim:blockfi:section:outlook_and_watch:2","claim:blockfi:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:blockfi:regulatory-penalties:2022-02-14","dimension":"regulatory_fines","label":"Combined SEC and state regulatory penalties","value":100000000,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-02-14","definition":"2022 settlement"},"as_of":"2022-02-14","method":"Settled federal and parallel state penalties.","scope":{"product":"BlockFi Lending LLC federal settlement and 32 parallel state actions","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:blockfi:metric:regulatory-penalties"],"quality_flags":["settlement","federal_and_state_combined","not_customer_recovery"]},{"id":"metric:blockfi:allowed-claim-distribution:2025-04-02","dimension":"creditor_recovery","label":"Announced distribution of allowed dollar claim amounts","value":100,"unit":"percent","currency":"PERCENT","window":{"start":null,"end":"2025-04-02","definition":"announced maximum distribution"},"as_of":"2025-04-02","method":"Plan-administrator announcement for eligible allowed claims.","scope":{"product":"Eligible BlockFi customers with allowed dollarized claims","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:blockfi:metric:allowed-claim-distribution"],"quality_flags":["allowed_dollar_claims_only","not_original_crypto_units","eligibility_and_identity_checks_apply","not_final_estate_closure"]}],"events":[{"id":"event:blockfi:sec-settlement","type":"regulatory","date":"2022-02-14","description":"BlockFi settled SEC and state interest-account cases for a combined $100 million.","claim_ids":["claim:blockfi:event:sec-settlement"]},{"id":"event:blockfi:chapter-11","type":"bankruptcy","date":"2022-11-28","description":"BlockFi Inc. and eight affiliates filed Chapter 11 cases.","claim_ids":["claim:blockfi:event:chapter-11"]},{"id":"event:blockfi:plan-effective","type":"restructuring","date":"2023-10-24","description":"The confirmed plan became effective and the company entered its distribution wind-down.","claim_ids":["claim:blockfi:event:plan-effective"]}],"sources":[{"id":"source:blockfi:sec-release","title":"BlockFi agrees to pay $100 million in penalties","url":"https://www.sec.gov/newsroom/press-releases/2022-26","publisher":"U.S. Securities and Exchange Commission","published_at":"2022-02-14","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"SEC findings on BlockFi Interest Accounts, the lending model, misleading risk statements and combined federal-state penalties.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:blockfi:sec-order","title":"In the matter of BlockFi Lending LLC","url":"https://www.sec.gov/files/litigation/admin/2022/33-11029.pdf","publisher":"U.S. Securities and Exchange Commission","published_at":"2022-02-14","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Administrative order and settled findings specific to BlockFi Lending LLC.","direct_http_status":403,"access_method":"indexed_pdf_snapshot"},{"id":"source:blockfi:court","title":"BlockFi Inc., 22-19361 (MBK)","url":"https://www.njb.uscourts.gov/BlockFi","publisher":"U.S. Bankruptcy Court for the District of New Jersey","published_at":null,"accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Official case page, debtor case number and current claims contact.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:blockfi:plan","title":"BlockFi final Chapter 11 plan","url":"https://blockfiofficialcommittee.com/downloads/BlockFi%20-%20Final%20Plan.pdf","publisher":"BlockFi Official Committee of Unsecured Creditors","published_at":"2023-09-25","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Court-filed final plan, entity-specific claim classes and distribution mechanics.","direct_http_status":200,"access_method":"direct_pdf"},{"id":"source:blockfi:claims","title":"BlockFi schedule and wallet information portal","url":"https://forms.ra.kroll.com/efiling/fr/claim-lookup/blockfi/new","publisher":"Kroll Restructuring Administration","published_at":null,"accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Current claims portal confirming nine Chapter 11 debtor filings and the jointly administered case.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:blockfi:distribution","title":"Verify identity to secure remaining BlockFi distributions","url":"https://ebs.publicnow.com/view/25EDAA69B80F8E62A1CF14CFD0CC3032DF8B7E08","publisher":"BlockFi Plan Administrator via Public","published_at":"2025-04-02","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Plan-administrator notice describing 100% of allowed dollarized claims for eligible customers and unfinished identity checks.","direct_http_status":403,"access_method":"indexed_browser_snapshot"},{"id":"source:blockfi:settlement","title":"In re BlockFi, Inc. securities litigation","url":"https://www.blockfisecuritiessettlement.com/","publisher":"BlockFi Securities Settlement","published_at":"2025-12-05","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Court-approved civil securities settlement and allocation process, separate from Chapter 11 distributions.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:blockfi:theblock","title":"BlockFi can begin repaying creditors after emerging from bankruptcy","url":"https://www.theblock.co/post/259262/blockfi-can-begin-repaying-creditors-after-emerging-from-bankruptcy","publisher":"The Block","published_at":"2023-10-24","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent report of the effective date, wind-down and contingent recoveries.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:blockfi:cnbc","title":"BlockFi files for bankruptcy as FTX contagion spreads","url":"https://www.cnbc.com/2022/11/28/blockfi-files-for-bankruptcy-as-ftx-contagion-spreads.html","publisher":"CNBC","published_at":"2022-11-28","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Contemporaneous independent bankruptcy filing and FTX-contagion context.","direct_http_status":403,"access_method":"browser_rendered_page"}],"claims":[{"id":"claim:blockfi:status","field_path":"status.operating_state","assertion":"BlockFi no longer operates its lending or trading products and remains in a plan-administered wind-down and distribution process.","value":"closed_plan_administration_and_distributions","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:court","source:blockfi:plan","source:blockfi:claims","source:blockfi:distribution"],"evidence_locator":"Official court, plan and administrator records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:outcome","field_path":"outcome.label","assertion":"BlockFi failed as a crypto lender and broker, but eligible customers were later positioned to receive the allowed dollar amount of their claims through the estate.","value":"failed_lender_in_wind_down_with_dollarized_claim_recovery","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:plan","source:blockfi:distribution","source:blockfi:theblock","source:blockfi:cnbc"],"evidence_locator":"Plan, administrator and independent wind-down records.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"BlockFi’s core product was interest-bearing crypto lending.","value":"BlockFi’s core product was interest-bearing crypto lending.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"SEC product and business-model findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"BlockFi also provided wallet, loan and trading surfaces.","value":"BlockFi also provided wallet, loan and trading surfaces.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan","source:blockfi:court"],"evidence_locator":"Plan claim classes and court customer categories.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"The operating company has been replaced by a wind-down and claims process.","value":"The operating company has been replaced by a wind-down and claims process.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan","source:blockfi:claims","source:blockfi:distribution"],"evidence_locator":"Court and administrator records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"BlockFi agreed to $100 million in combined federal and state penalties.","value":"BlockFi agreed to $100 million in combined federal and state penalties.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"SEC settlement terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"BlockFi filed Chapter 11 on November 28, 2022.","value":"BlockFi filed Chapter 11 on November 28, 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:court","source:blockfi:claims","source:blockfi:cnbc"],"evidence_locator":"Court and contemporaneous report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"The effective plan began a managed wind-down and recovery process.","value":"The effective plan began a managed wind-down and recovery process.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan","source:blockfi:theblock"],"evidence_locator":"Plan and effective-date report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Interest-account returns depended on BlockFi lending or investing customer assets.","value":"Interest-account returns depended on BlockFi lending or investing customer assets.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"Regulatory description of the pooled model.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"The SEC found a misleading statement about loan-portfolio risk.","value":"The SEC found a misleading statement about loan-portfolio risk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"Settled administrative finding.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"FTX failure was the immediate bankruptcy trigger rather than the entire structural cause.","value":"FTX failure was the immediate bankruptcy trigger rather than the entire structural cause.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:cnbc","source:blockfi:plan"],"evidence_locator":"Filing chronology and plan recovery claims.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"BlockFi combined retail yield with institutional lending and other account products.","value":"BlockFi combined retail yield with institutional lending and other account products.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:plan"],"evidence_locator":"Regulatory and plan descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"BlockFi proposed a registered successor product after the SEC settlement.","value":"BlockFi proposed a registered successor product after the SEC settlement.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release"],"evidence_locator":"Company commitment described by the SEC.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"The confirmed plan pursued wind-down rather than a consumer relaunch.","value":"The confirmed plan pursued wind-down rather than a consumer relaunch.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:plan","source:blockfi:theblock"],"evidence_locator":"Plan mechanics and effective-date report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"BlockFi Interest Account holders lent crypto to BlockFi for variable monthly yield.","value":"BlockFi Interest Account holders lent crypto to BlockFi for variable monthly yield.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"SEC operating-model findings.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Different products and debtor entities received different plan classes.","value":"Different products and debtor entities received different plan classes.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan"],"evidence_locator":"Final plan classification.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"Trading was a platform surface within a lending model, not the core order-book business.","value":"Trading was a platform surface within a lending model, not the core order-book business.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:sec-release","source:blockfi:plan"],"evidence_locator":"Analyst taxonomy based on the documented products.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"No BlockFi venue token is identified in the reviewed official record.","value":"No BlockFi venue token is identified in the reviewed official record.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:blockfi:sec-order","source:blockfi:plan"],"evidence_locator":"Regulatory and plan document review.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"The lending spread was the core value-capture mechanism.","value":"The lending spread was the core value-capture mechanism.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"Regulatory business-model description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Bankruptcy recovery followed account and debtor claim classes.","value":"Bankruptcy recovery followed account and debtor claim classes.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan","source:blockfi:claims"],"evidence_locator":"Court-approved distribution structure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Diversification and liquidity buffers directly address the documented counterparty model.","value":"Diversification and liquidity buffers directly address the documented counterparty model.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:sec-order","source:blockfi:plan"],"evidence_locator":"Analyst counterfactual grounded in exposures.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Product segregation would have clarified different customer legal positions.","value":"Product segregation would have clarified different customer legal positions.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:plan"],"evidence_locator":"Analyst counterfactual grounded in plan classes.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"Whether BlockFi could have survived without failed-counterparty recoveries is answered negatively by the wind-down plan.","value":"Whether BlockFi could have survived without failed-counterparty recoveries is answered negatively by the wind-down plan.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:plan","source:blockfi:theblock"],"evidence_locator":"Plan dependence on recoveries.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Some remaining distributions required identity verification in 2025.","value":"Some remaining distributions required identity verification in 2025.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:distribution"],"evidence_locator":"Plan-administrator notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The 100% statement is limited to allowed dollarized claim amounts.","value":"The 100% statement is limited to allowed dollarized claim amounts.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:distribution","source:blockfi:plan"],"evidence_locator":"Administrator language and plan valuation mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The securities settlement is separate from Chapter 11 distributions.","value":"The securities settlement is separate from Chapter 11 distributions.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:settlement","source:blockfi:court"],"evidence_locator":"Distinct case and allocation process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"BlockFi’s operating lifecycle ended in the 2022 bankruptcy.","value":"BlockFi’s operating lifecycle ended in the 2022 bankruptcy.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:court","source:blockfi:cnbc"],"evidence_locator":"Filing chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The plan became effective in October 2023 and enabled distributions.","value":"The plan became effective in October 2023 and enabled distributions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan","source:blockfi:theblock"],"evidence_locator":"Effective-date record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"Strong dollar-claim recovery does not mean the lender relaunched.","value":"Strong dollar-claim recovery does not mean the lender relaunched.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:distribution","source:blockfi:claims"],"evidence_locator":"Administrator and claims records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Court and claims-agent updates are the authoritative remaining milestones.","value":"Court and claims-agent updates are the authoritative remaining milestones.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:court","source:blockfi:claims"],"evidence_locator":"Official current sources.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"No reviewed plan provides for a BlockFi operating relaunch.","value":"No reviewed plan provides for a BlockFi operating relaunch.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:blockfi:plan","source:blockfi:theblock"],"evidence_locator":"Wind-down design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Final claimant-specific economic recovery remains unknown.","value":"Final claimant-specific economic recovery remains unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:blockfi:distribution","source:blockfi:settlement"],"evidence_locator":"Dollarization and separate recovery pools.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:metric:regulatory-penalties","field_path":"metrics[metric:blockfi:regulatory-penalties:2022-02-14].value","assertion":"Combined SEC and state regulatory penalties was 100000000 USD for the stated scope and date.","value":100000000,"as_of":"2022-02-14","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"Source observation checked at 2026-08-03T22:00:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:metric:allowed-claim-distribution","field_path":"metrics[metric:blockfi:allowed-claim-distribution:2025-04-02].value","assertion":"Announced distribution of allowed dollar claim amounts was 100 PERCENT for the stated scope and date.","value":100,"as_of":"2025-04-02","confidence":"high","kind":"fact","source_ids":["source:blockfi:distribution","source:blockfi:plan"],"evidence_locator":"Source observation checked at 2026-08-03T22:00:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:event:sec-settlement","field_path":"events[event:blockfi:sec-settlement]","assertion":"BlockFi settled SEC and state interest-account cases for a combined $100 million.","value":"2022-02-14","as_of":"2022-02-14","confidence":"high","kind":"fact","source_ids":["source:blockfi:sec-release","source:blockfi:sec-order"],"evidence_locator":"Regulator settlement record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:event:chapter-11","field_path":"events[event:blockfi:chapter-11]","assertion":"BlockFi Inc. and eight affiliates filed Chapter 11 cases.","value":"2022-11-28","as_of":"2022-11-28","confidence":"high","kind":"fact","source_ids":["source:blockfi:court","source:blockfi:claims","source:blockfi:cnbc"],"evidence_locator":"Court and claims records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:blockfi:event:plan-effective","field_path":"events[event:blockfi:plan-effective]","assertion":"The confirmed plan became effective and the company entered its distribution wind-down.","value":"2023-10-24","as_of":"2023-10-24","confidence":"high","kind":"fact","source_ids":["source:blockfi:plan","source:blockfi:theblock"],"evidence_locator":"Plan and effective-date report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:00:00Z","next_review_at":"2026-08-10T22:00:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Final unclaimed distribution amount","Final estate closure costs","Claimant-specific market-value loss","Final securities-settlement payout"]},"extensions":{"legacy_origin":"dead_exchanges","identity_boundary":"BlockFi was primarily a lender and yield platform with wallet, loan and brokerage-style trading surfaces, not a conventional order-book exchange. BlockFi Inc., BlockFi Lending LLC, BlockFi International Ltd. and other debtors have distinct claim classes. The Chapter 11 estate and the later civil securities settlement are separate recovery processes.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, custody liabilities and tokens are kept separate.","A 100% distribution refers to the allowed dollarized claim amount, not restoration of the original crypto quantity or its later market value.","The SEC settlement findings were entered without BlockFi admitting or denying them, except as to jurisdiction; criminal guilt is not asserted."],"explicit_unknowns":["Unfinished distributions after identity or jurisdiction checks","Final administrative costs and unresolved claims","Economic loss versus original crypto units and later prices","Allocation from the separate civil securities settlement"]}}', '{"kind":"cex","slug":"blockfi","lifecycle":"dead","operating_model":"Closed crypto lender and broker whose distinct debtor estates distribute allowed claims under a Chapter 11 plan.","product_cohort":"centralized_crypto_lender_and_broker","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"not_identified","token_symbol":null,"token_launch_date":null,"token_launch_timing":"unknown","token_strategy":"no_venue_token_identified","token_source_url":"https://www.sec.gov/newsroom/press-releases/2022-26","metric_type":"creditor_recovery","metric_unit":"percent","metric_window":"allowed_dollar_claim_distribution","metric_as_of":"2025-04-02","metric_observed_at":"2026-08-03T22:00:00Z","comparability_key":"cex|centralized_crypto_lender_and_broker|creditor_recovery|percent|allowed_dollar_claims","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"BlockFi was primarily a lender and yield platform with wallet, loan and brokerage-style trading surfaces, not a conventional order-book exchange. BlockFi Inc., BlockFi Lending LLC, BlockFi International Ltd. and other debtors have distinct claim classes. The Chapter 11 estate and the later civil securities settlement are separate recovery processes.","source_count":9},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_f_profiles_0101 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'celsius', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:celsius","type":"cex","slug":"celsius","name":"Celsius Network","aliases":["Celsius","Celsius Network LLC"]},"classification":{"subtype":"failed crypto lender and yield platform in post-confirmation administration","tags":["lender","earn","loans","custodial","bankruptcy","fraud-conviction","exchange-token"],"chains":[],"jurisdictions":["United States","United Kingdom"]},"status":{"operating_state":"closed_post_effective_date_distributions","as_of":"2026-08-03","claim_ids":["claim:celsius:status"]},"outcome":{"label":"failed_lender_after_fraud_liquidity_and_risk_failures","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:celsius:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Celsius was a custodial crypto lender and yield platform, not a standard order-book exchange. Its main Earn product paid rewards on deposited assets; Borrow offered collateralized loans; Custody and swap features broadened the app. Customers transferred control of assets to Celsius while the company deployed them for yield. The app is now closed, and the remaining organization exists to make plan distributions and pursue or defend claims.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:what_it_is:1","claim:celsius:section:what_it_is:2","claim:celsius:section:what_it_is:3"]},"what_happened":{"body":"Celsius halted withdrawals on June 12, 2022 with roughly $4.7 billion of customer assets inaccessible, then filed Chapter 11 on July 13. Regulators later described misleading safety, liquidity and business claims. Founder Alex Mashinsky pleaded guilty to commodities and securities fraud and was sentenced to 12 years in May 2025; the Justice Department also documented manipulation of CEL. A reorganization plan became effective in January 2024 and the consumer app closed the next month.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:what_happened:1","claim:celsius:section:what_happened:2","claim:celsius:section:what_happened:3"]},"why_this_outcome":{"body":"Celsius promised liquid, bank-like access while using customer assets for loans, trading and other risky strategies. The FTC said unsecured lending reached $1.2 billion by April 2022 and reserves could cover only a fraction of withdrawals. The criminal record also shows management misrepresented stability and used large purchases to support CEL. When markets turned and customers demanded assets back, the platform lacked the liquid resources and trust needed to honor the promise.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:why_this_outcome:1","claim:celsius:section:why_this_outcome:2","claim:celsius:section:why_this_outcome:3"]},"strategic_choices":{"body":"Celsius chose rapid growth through high reward rates, broad retail marketing and the “unbank yourself” message. It concentrated multiple products and balance-sheet risks in one app, made unsecured institutional loans, and supported CEL through company purchases. Those choices made growth depend on continued deposits, asset prices and trust. The later plan chose distributions plus a mining successor structure instead of trying to revive the lender, while permanently shutting the consumer app.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:strategic_choices:1","claim:celsius:section:strategic_choices:2","claim:celsius:section:strategic_choices:3"]},"operating_model":{"body":"Customers deposited crypto into Celsius accounts and, for Earn, exchanged asset control for promised variable rewards. Celsius pooled assets, made secured and unsecured loans, invested or traded, used deposits in operations and offered loans against customer collateral. Revenue had to exceed reward obligations and losses while enough liquid assets remained for withdrawals. That fragile balance was hidden by internal risk and disclosure failures until withdrawals were stopped.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:operating_model:1","claim:celsius:section:operating_model:2","claim:celsius:section:operating_model:3"]},"token_and_value_capture":{"body":"CEL was the platform token used in rewards and promoted as part of the Celsius ecosystem. The Justice Department established that Mashinsky and others used hundreds of millions of dollars of purchases, sometimes funded with customer deposits, to inflate CEL while he sold personal holdings. That is not healthy token value capture; it is manipulation tied to executive extraction. In the bankruptcy, CEL claim treatment is a plan question, not proof of market value or redemption backing.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:token_and_value_capture:1","claim:celsius:section:token_and_value_capture:2","claim:celsius:section:token_and_value_capture:3"]},"counterfactual":{"body":"Transparent asset-liability reporting, conservative reward rates, limits on unsecured credit and a real liquidity buffer could have reduced the run risk. Independent controls over CEL purchases and executive sales could have exposed manipulation earlier. Product-level segregation could also have made custody and yield risks clearer. These controls do not guarantee survival, but they directly address the documented mismatch between customer promises, hidden risk-taking and management incentives.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:counterfactual:1","claim:celsius:section:counterfactual:2","claim:celsius:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The lender is not coming back, but creditors still face distribution, identity, tax, claim and litigation uncertainty. Current case notices warn of phishing and show that some classes and later distributions remain active. Recovery should not be summarized with one percentage because crypto, cash, claim class and successor equity differ. Civil allegations against defendants other than those whose cases resolved must remain attributed, while Mashinsky’s plea and sentence can be stated as established facts.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:risks_and_unknowns:1","claim:celsius:section:risks_and_unknowns:2","claim:celsius:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Celsius launched in 2017, grew to roughly $25 billion in assets at its peak, and built its brand around high-yield retail accounts and CEL. The model broke during the 2022 credit crisis, withdrawals stopped and Chapter 11 followed. A court confirmed the plan in November 2023; it became effective January 31, 2024, and the app shut February 29. Mashinsky’s 2025 sentence closed the main criminal founder case while estate distributions continued.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:lifecycle:1","claim:celsius:section:lifecycle:2","claim:celsius:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch the Stretto docket for later distributions, claim reconciliations, estate litigation and final wind-down reports. Track successor-company equity separately from cash or crypto payments, and do not confuse app closure with completion of the estate. No credible evidence supports a Celsius lending relaunch. The final success measure is how much each class actually realizes after time, costs and valuation effects, not the size of a judgment or the token’s quoted price.","as_of":"2026-08-03","claim_ids":["claim:celsius:section:outlook_and_watch:1","claim:celsius:section:outlook_and_watch:2","claim:celsius:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:celsius:inaccessible-customer-assets:2022-06-12","dimension":"customer_assets","label":"Customer assets inaccessible when withdrawals stopped","value":4700000000,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-06-12","definition":"withdrawal-halt observation"},"as_of":"2022-06-12","method":"Justice Department sentencing release.","scope":{"product":"Celsius customer assets inaccessible on the platform","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:celsius:metric:inaccessible-customer-assets"],"quality_flags":["approximate","customer_assets_not_shortfall","not_additive_with_ftc_judgment"]}],"events":[{"id":"event:celsius:withdrawal-halt","type":"withdrawal_halt","date":"2022-06-12","description":"Celsius halted customer withdrawals.","claim_ids":["claim:celsius:event:withdrawal-halt"]},{"id":"event:celsius:chapter-11","type":"bankruptcy","date":"2022-07-13","description":"Celsius and affiliated debtors filed Chapter 11 cases.","claim_ids":["claim:celsius:event:chapter-11"]},{"id":"event:celsius:plan-effective","type":"restructuring","date":"2024-01-31","description":"The confirmed Celsius plan became effective and distributions began.","claim_ids":["claim:celsius:event:plan-effective"]},{"id":"event:celsius:mashinsky-sentencing","type":"criminal_disposition","date":"2025-05-08","description":"Alex Mashinsky was sentenced to 12 years after pleading guilty to commodities and securities fraud.","claim_ids":["claim:celsius:event:mashinsky-sentencing"]}],"sources":[{"id":"source:celsius:stretto","title":"Celsius Network LLC, et al.","url":"https://cases.stretto.com/celsius","publisher":"Stretto","published_at":null,"accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Official case hub, January 31, 2024 effective date and current distribution notices.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:celsius:app-close","title":"Celsius distribution inquiries","url":"https://cases.stretto.com/celsius/contact-us/","publisher":"Stretto","published_at":null,"accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_l