:null,"evidence_locator":"Current FTC case page separating Celsius entities and individual-defendant resolutions.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:celsius:sec","title":"Celsius Network Limited and Alexander Mashinsky","url":"https://www.sec.gov/enforcement-litigation/litigation-releases/lr-25779","publisher":"U.S. Securities and Exchange Commission","published_at":"2023-07-14","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"SEC allegations concerning Earn, business disclosures and CEL market manipulation.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:celsius:court-2026","title":"Post-effective-date Celsius court filing","url":"https://cases.stretto.com/public/x191/11749/PLEADINGS/1174903162680000000335.pdf","publisher":"U.S. Bankruptcy Court for the Southern District of New York","published_at":"2026-03-16","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Court filing confirming the plan, effective date and continuing post-effective-date administration.","direct_http_status":200,"access_method":"direct_pdf"},{"id":"source:celsius:cnbc","title":"Celsius founder Alex Mashinsky sentenced to 12 years","url":"https://www.cnbc.com/2025/05/08/celsius-ceo-alex-mashinsky-sentenced-to-12-years-in-crypto-fraud-case.html","publisher":"CNBC","published_at":"2025-05-08","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent sentencing coverage and customer-loss context.","direct_http_status":403,"access_method":"browser_rendered_page"}],"claims":[{"id":"claim:celsius:status","field_path":"status.operating_state","assertion":"The Celsius consumer platform and app are closed, while post-effective-date debtors and claims agents continue distributions and litigation.","value":"closed_post_effective_date_distributions","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:stretto","source:celsius:app-close","source:celsius:court-2026"],"evidence_locator":"Official case hub, app shutdown notice and 2026 court filing.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:outcome","field_path":"outcome.label","assertion":"Celsius failed as a crypto lender after liquidity, risk and disclosure failures that included founder fraud and CEL manipulation proven by Mashinsky’s guilty plea.","value":"failed_lender_after_fraud_liquidity_and_risk_failures","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:doj","source:celsius:stretto","source:celsius:ftc","source:celsius:sec"],"evidence_locator":"Criminal disposition, regulator records and bankruptcy administration.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Celsius offered Earn, Borrow, Custody and exchange-like services.","value":"Celsius offered Earn, Borrow, Custody and exchange-like services.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:doj","source:celsius:ftc"],"evidence_locator":"Government product descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Earn customers transferred assets for promised yield.","value":"Earn customers transferred assets for promised yield.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:sec","source:celsius:doj"],"evidence_locator":"SEC and criminal case descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"The app is closed and only post-plan administration remains.","value":"The app is closed and only post-plan administration remains.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:app-close","source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Official case and shutdown records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Celsius halted withdrawals on June 12, 2022 with about $4.7 billion inaccessible.","value":"Celsius halted withdrawals on June 12, 2022 with about $4.7 billion inaccessible.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:doj"],"evidence_locator":"Criminal sentencing release.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Celsius filed Chapter 11 on July 13, 2022.","value":"Celsius filed Chapter 11 on July 13, 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:stretto","source:celsius:ftc"],"evidence_locator":"Official case records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"Mashinsky pleaded guilty and received a 12-year sentence.","value":"Mashinsky pleaded guilty and received a 12-year sentence.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:doj","source:celsius:cnbc"],"evidence_locator":"Criminal disposition and independent coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Celsius deployed customer assets into lending and risky investments.","value":"Celsius deployed customer assets into lending and risky investments.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:ftc","source:celsius:doj"],"evidence_locator":"Government findings and criminal record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"The FTC alleged $1.2 billion of unsecured loans by April 2022.","value":"The FTC alleged $1.2 billion of unsecured loans by April 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:ftc"],"evidence_locator":"FTC complaint summary.","support_direction":"supports","note":"An FTC allegation against the Celsius enterprise, not a separate criminal finding.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Liquidity stress exposed the mismatch between withdrawal promises and deployed assets.","value":"Liquidity stress exposed the mismatch between withdrawal promises and deployed assets.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:ftc","source:celsius:doj"],"evidence_locator":"Analyst causal synthesis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Celsius marketed high rewards and a bank alternative to retail customers.","value":"Celsius marketed high rewards and a bank alternative to retail customers.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:ftc","source:celsius:doj"],"evidence_locator":"Government marketing records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"Celsius used unsecured lending and company CEL purchases.","value":"Celsius used unsecured lending and company CEL purchases.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:ftc","source:celsius:doj"],"evidence_locator":"FTC allegations and criminally established manipulation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"The plan wound down the app rather than relaunching the lender.","value":"The plan wound down the app rather than relaunching the lender.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:stretto","source:celsius:app-close","source:celsius:court-2026"],"evidence_locator":"Post-confirmation records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Earn transferred customer assets into a pooled yield model.","value":"Earn transferred customer assets into a pooled yield model.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:sec","source:celsius:doj"],"evidence_locator":"Regulatory and criminal descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Celsius made both secured and unsecured loans and used deposits in operations.","value":"Celsius made both secured and unsecured loans and used deposits in operations.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:ftc"],"evidence_locator":"FTC complaint summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"The business required yield and liquidity to cover customer obligations.","value":"The business required yield and liquidity to cover customer obligations.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:ftc","source:celsius:doj"],"evidence_locator":"Analyst operating-model inference.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"CEL was promoted as Celsius’s platform token.","value":"CEL was promoted as Celsius’s platform token.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:sec","source:celsius:doj"],"evidence_locator":"Regulatory and criminal records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Mashinsky’s manipulation scheme used large CEL purchases and enabled personal sales.","value":"Mashinsky’s manipulation scheme used large CEL purchases and enabled personal sales.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:doj"],"evidence_locator":"Guilty plea and sentencing facts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"Bankruptcy treatment of CEL does not establish token backing or redemption value.","value":"Bankruptcy treatment of CEL does not establish token backing or redemption value.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Analyst legal and market boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Liquidity buffers and lower unsecured exposure address the documented withdrawal mismatch.","value":"Liquidity buffers and lower unsecured exposure address the documented withdrawal mismatch.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:ftc","source:celsius:doj"],"evidence_locator":"Analyst counterfactual.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Independent CEL controls address the proven manipulation scheme.","value":"Independent CEL controls address the proven manipulation scheme.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:doj"],"evidence_locator":"Analyst counterfactual.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"Product segregation could have clarified custody versus yield risk.","value":"Product segregation could have clarified custody versus yield risk.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:stretto","source:celsius:ftc"],"evidence_locator":"Analyst counterfactual grounded in product classes.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Post-effective-date distributions and communications remained active in 2025 and 2026.","value":"Post-effective-date distributions and communications remained active in 2025 and 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Current case records.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Recovery differs by claim class and distribution component.","value":"Recovery differs by claim class and distribution component.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Plan-administration structure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Unresolved civil allegations remain allegations.","value":"Unresolved civil allegations remain allegations.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:celsius:sec","source:celsius:ftc-case"],"evidence_locator":"Procedural boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"Celsius held approximately $25 billion in assets at its peak.","value":"Celsius held approximately $25 billion in assets at its peak.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:doj"],"evidence_locator":"DOJ historical scale figure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The plan became effective January 31, 2024 and the app closed February 29.","value":"The plan became effective January 31, 2024 and the app closed February 29.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:celsius:stretto","source:celsius:app-close","source:celsius:court-2026"],"evidence_locator":"Official dates.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"The operating lifecycle ended while estate administration continued.","value":"The operating lifecycle ended while estate administration continued.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:stretto","source:celsius:app-close"],"evidence_locator":"Analyst lifecycle boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"The Stretto case hub is the authoritative source for remaining distributions.","value":"The Stretto case hub is the authoritative source for remaining distributions.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Current official case channel.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"No reviewed plan record supports a Celsius lender relaunch.","value":"No reviewed plan record supports a Celsius lender relaunch.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:celsius:app-close","source:celsius:stretto"],"evidence_locator":"Wind-down and app closure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Final class-level realized recovery remains unknown.","value":"Final class-level realized recovery remains unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Ongoing administration.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:metric:inaccessible-customer-assets","field_path":"metrics[metric:celsius:inaccessible-customer-assets:2022-06-12].value","assertion":"Customer assets inaccessible when withdrawals stopped was 4700000000 USD for the stated scope and date.","value":4700000000,"as_of":"2022-06-12","confidence":"high","kind":"fact","source_ids":["source:celsius:doj"],"evidence_locator":"Source observation checked at 2026-08-03T22:00:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:event:withdrawal-halt","field_path":"events[event:celsius:withdrawal-halt]","assertion":"Celsius halted customer withdrawals.","value":"2022-06-12","as_of":"2022-06-12","confidence":"high","kind":"fact","source_ids":["source:celsius:doj","source:celsius:ftc"],"evidence_locator":"Government chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:event:chapter-11","field_path":"events[event:celsius:chapter-11]","assertion":"Celsius and affiliated debtors filed Chapter 11 cases.","value":"2022-07-13","as_of":"2022-07-13","confidence":"high","kind":"fact","source_ids":["source:celsius:stretto","source:celsius:ftc"],"evidence_locator":"Official case record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:event:plan-effective","field_path":"events[event:celsius:plan-effective]","assertion":"The confirmed Celsius plan became effective and distributions began.","value":"2024-01-31","as_of":"2024-01-31","confidence":"high","kind":"fact","source_ids":["source:celsius:stretto","source:celsius:court-2026"],"evidence_locator":"Official effective-date record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:celsius:event:mashinsky-sentencing","field_path":"events[event:celsius:mashinsky-sentencing]","assertion":"Alex Mashinsky was sentenced to 12 years after pleading guilty to commodities and securities fraud.","value":"2025-05-08","as_of":"2025-05-08","confidence":"high","kind":"fact","source_ids":["source:celsius:doj","source:celsius:cnbc"],"evidence_locator":"Criminal disposition.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:00:00Z","next_review_at":"2026-08-10T22:00:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Final class-level recovery","Final unclaimed property amount","Realized successor-equity value","Final unresolved civil case outcomes"]},"extensions":{"legacy_origin":"dead_exchanges","identity_boundary":"Celsius was primarily a lender and yield platform with loans, custody and exchange-like swap features, not a conventional order-book exchange. Celsius debtor entities, the post-effective-date estate, Alexander Mashinsky, other executives and the successor mining company are separate subjects. Mashinsky’s fraud and manipulation are proven by his plea and sentence; SEC and FTC allegations against other parties remain allegations unless resolved.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, custody liabilities and tokens are kept separate.","The $4.7 billion customer-assets figure in the DOJ release is not the same metric as the FTC’s separately suspended $4.7 billion corporate judgment and must not be added to it.","Bankruptcy distributions, successor-company shares and litigation proceeds are distinct recovery components."],"explicit_unknowns":["Final creditor recovery by claim class","Remaining disputed and unclaimed distributions","Net value ultimately realized from successor-company equity","Final resolution of civil claims against non-settling defendants"]}}', '{"kind":"cex","slug":"celsius","lifecycle":"dead","operating_model":"Closed crypto lender and yield platform whose post-effective-date debtors continue distributions and litigation.","product_cohort":"centralized_crypto_lender_and_yield_platform","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"launched","token_symbol":"CEL","token_launch_date":"2018-03-22","token_launch_timing":"post_product","token_strategy":"rewards_and_platform_utility_with_proven_manipulation","token_source_url":"https://www.justice.gov/usao-sdny/pr/founder-celsius-sentenced-12-years-fraud-and-market-manipulation","metric_type":"customer_assets","metric_unit":"usd","metric_window":"withdrawal_halt_observation","metric_as_of":"2022-06-12","metric_observed_at":"2026-08-03T22:00:00Z","comparability_key":"cex|centralized_crypto_lender_and_yield_platform|customer_assets|usd|withdrawal_halt","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"Celsius was primarily a lender and yield platform with loans, custody and exchange-like swap features, not a conventional order-book exchange. Celsius debtor entities, the post-effective-date estate, Alexander Mashinsky, other executives and the successor mining company are separate subjects. Mashinsky’s fraud and manipulation are proven by his plea and sentence; SEC and FTC allegations against other parties remain allegations unless resolved.","source_count":8},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_f_profiles_0101 (
  target_table, slug, canonical_profile, feature
) VALUES ('dead_exchanges', 'coinflex', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:coinflex","type":"cex","slug":"coinflex","name":"CoinFLEX","aliases":["CoinFLEX Exchange","Liquidity Technologies Ltd."]},"classification":{"subtype":"closed custodial derivatives exchange in creditor restructuring and litigation","tags":["custodial","derivatives","withdrawal-halt","restructuring","counterparty-risk","recovery-token","exchange-token"],"chains":[],"jurisdictions":["Seychelles","Hong Kong"]},"status":{"operating_state":"closed_restructured_with_disputed_recoveries","as_of":"2026-08-03","claim_ids":["claim:coinflex:status"]},"outcome":{"label":"failed_after_concentrated_counterparty_exposure_and_restructuring","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"high","claim_ids":["claim:coinflex:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"CoinFLEX was a custodial crypto derivatives exchange whose customers traded futures and other products through balances controlled by the venue. It also used FLEX as a venue token, issued flexUSD as an interest-bearing stablecoin product and later proposed rvUSD as a recovery claim. Trading has ended. The surviving story is a Seychelles restructuring, creditor rights and litigation, not an active exchange or a clean rebrand into OPNX.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:what_it_is:1","claim:coinflex:section:what_it_is:2","claim:coinflex:section:what_it_is:3"]},"what_happened":{"body":"CoinFLEX halted withdrawals in June 2022 after a large customer account went negative. The company identified Roger Ver and first described a $47 million gap; Ver denied owing it. By the Seychelles filing, CoinFLEX asserted an $84 million debt and proposed dollarizing customer positions, applying a haircut, and giving creditors equity plus pro-rata rights to recovery through rvUSD. A court approved the restructuring in March 2023, and trading later ceased.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:what_happened:1","claim:coinflex:section:what_happened:2","claim:coinflex:section:what_happened:3"]},"why_this_outcome":{"body":"The direct cause was concentrated counterparty credit: CoinFLEX allowed one customer position to create a balance-sheet hole large enough to stop withdrawals. The court record says the position could not be liquidated under an arrangement with the customer, making the venue an unsecured creditor when the market moved. Tokenizing the claim did not restore cash or liquid assets; it transferred recovery uncertainty to users. That is a risk-control failure, not simply a market downturn.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:why_this_outcome:1","claim:coinflex:section:why_this_outcome:2","claim:coinflex:section:why_this_outcome:3"]},"strategic_choices":{"body":"CoinFLEX chose to grant special margin treatment to a large customer instead of enforcing ordinary automatic liquidation, concentrating solvency risk in a bilateral arrangement. After the shortfall, it chose a novel token-and-equity restructuring rather than immediate liquidation: balances were dollarized and creditors received mixed consideration. Management later associated CoinFLEX with OPNX, but subsequent litigation disputed asset and brand transfers, so the successor story cannot be presented as settled.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:strategic_choices:1","claim:coinflex:section:strategic_choices:2","claim:coinflex:section:strategic_choices:3"]},"operating_model":{"body":"Customers posted collateral and traded derivatives on CoinFLEX while the venue controlled accounts, margin rules and withdrawals. Normal risk management should liquidate under-margined positions before they become exchange losses. CoinFLEX said a special agreement prevented that for the disputed customer, leaving the platform with a large receivable and insufficient liquid value for withdrawals. After restructuring, account balances became dollar claims, equity interests and recovery-token rights instead of freely withdrawable exchange balances.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:operating_model:1","claim:coinflex:section:operating_model:2","claim:coinflex:section:operating_model:3"]},"token_and_value_capture":{"body":"FLEX was CoinFLEX’s venue token, while flexUSD was a separate stablecoin product and rvUSD represented contingent recovery value. The restructuring also proposed locked FLEX and company equity for creditors. None of those instruments was equivalent to cash or a guaranteed redemption. Their value depended on venue activity, company value and successful collection of the disputed claim. OPNX later used a different OX token, which should not be merged into CoinFLEX’s recovery math.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:token_and_value_capture:1","claim:coinflex:section:token_and_value_capture:2","claim:coinflex:section:token_and_value_capture:3"]},"counterfactual":{"body":"Enforcing normal liquidation rules, capping single-counterparty exposure, requiring additional collateral and independently reviewing exceptions could have prevented one account from threatening all withdrawals. Once the gap existed, a cash recapitalization or transparent liquidation could have given creditors simpler rights than several volatile instruments, though neither was assured. The key counterfactual is whether the disputed position would have been liquidated earlier under ordinary rules; the court record says the exception prevented that.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:counterfactual:1","claim:coinflex:section:counterfactual:2","claim:coinflex:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The exchange is closed, but recovery uncertainty remains. The central unknown is how much, if anything, was collected on the disputed $84 million claim; the court filing proves that CoinFLEX asserted it, not that Ver legally owed or paid it. Creditor outcomes also depend on equity, token liquidity and restructuring costs. Separate Hong Kong allegations over OPNX-related assets and FLEX transfers remain contested and should not be described as findings.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:risks_and_unknowns:1","claim:coinflex:section:risks_and_unknowns:2","claim:coinflex:section:risks_and_unknowns:3"]},"lifecycle":{"body":"CoinFLEX launched in 2019 as a derivatives venue, expanded into exchange and stablecoin tokens, then stopped withdrawals in June 2022 when a concentrated counterparty position created a hole. Seychelles reorganization followed, with court approval in March 2023. Trading officially ceased October 31, 2023. OPNX operated afterward and closed in 2024, but disputed ownership and transfer claims prevent treating it as a clean continuation. CoinFLEX’s lifecycle is failure followed by contested recovery.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:lifecycle:1","claim:coinflex:section:lifecycle:2","claim:coinflex:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch court and restructuring records for actual recovery on the disputed claim, distributions from the rvUSD vehicle, equity outcomes and resolution of CoinFLEX/OPNX asset litigation. Do not use FLEX or OX market prices as a substitute for creditor recovery. A better outcome requires cash realization and distributable value; a worse one leaves creditors with illiquid instruments and unresolved claims. No reviewed evidence supports a CoinFLEX exchange relaunch.","as_of":"2026-08-03","claim_ids":["claim:coinflex:section:outlook_and_watch:1","claim:coinflex:section:outlook_and_watch:2","claim:coinflex:section:outlook_and_watch:3"]}}},"metrics":[{"id":"metric:coinflex:company-claimed-counterparty-debt:2022-08-17","dimension":"customer_shortfall","label":"CoinFLEX-claimed counterparty debt assigned to recovery rights","value":84000000,"unit":"usd","currency":"USD","window":{"start":null,"end":"2022-08-17","definition":"reorganization application"},"as_of":"2022-08-17","method":"Company claim reproduced in the reorganization record and paired with the counterparty denial.","scope":{"product":"Claim assigned to the proposed CoinFLEX recovery vehicle","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:coinflex:metric:company-claimed-counterparty-debt"],"quality_flags":["company_claim_not_adjudicated","counterparty_disputed","not_proven_customer_loss","not_final_recovery"]}],"events":[{"id":"event:coinflex:withdrawal-halt","type":"withdrawal_halt","date":"2022-06-23","description":"CoinFLEX halted withdrawals after a large counterparty position produced a claimed shortfall.","claim_ids":["claim:coinflex:event:withdrawal-halt"]},{"id":"event:coinflex:interim-reorganization","type":"restructuring","date":"2022-08-17","description":"The Seychelles court granted interim approval for the proposed reorganization process.","claim_ids":["claim:coinflex:event:interim-reorganization"]},{"id":"event:coinflex:plan-approved","type":"restructuring","date":"2023-03-06","description":"The Seychelles court approved the restructuring plan.","claim_ids":["claim:coinflex:event:plan-approved"]},{"id":"event:coinflex:trading-ceased","type":"closure","date":"2023-10-31","description":"CoinFLEX trading officially ceased.","claim_ids":["claim:coinflex:event:trading-ceased"]}],"sources":[{"id":"source:coinflex:seychelles","title":"Ex parte Liquidity Technologies Limited","url":"https://seylii.org/akn/sc/judgment/scsc/2022/718/eng%402022-08-17/source.pdf","publisher":"Supreme Court of Seychelles","published_at":"2022-08-17","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Interim reorganization order, balance-sheet hole, dollarization, creditor groups, proposed equity and recovery-token terms.","direct_http_status":404,"access_method":"indexed_pdf_snapshot"},{"id":"source:coinflex:wipo","title":"WIPO domain name dispute D2025-3478","url":"https://www.wipo.int/amc/en/domains/decisions/pdf/2025/d2025-3478.pdf","publisher":"World Intellectual Property Organization","published_at":"2025-12-19","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Decision identifying Liquidity Technologies, CoinFLEX brand use and the October 31, 2023 trading cessation date.","direct_http_status":200,"access_method":"direct_pdf"},{"id":"source:coinflex:hong-kong","title":"Liquidity Technologies Ltd v. Mark David Lamb and others","url":"https://lawhero.io/cases/183113/hca1646-2023-liquidity-technologies-ltd-and-another-v-mark-david-lamb-and-others","publisher":"Hong Kong Court case summary via LawHero","published_at":"2026-04-01","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Procedural summary of pleaded CoinFLEX/OPNX asset, technology and token disputes; allegations are not treated as findings.","direct_http_status":404,"access_method":"indexed_browser_snapshot"},{"id":"source:coinflex:decrypt-plan","title":"Seychelles court approves CoinFLEX restructuring plan","url":"https://decrypt.co/122887","publisher":"Decrypt","published_at":"2023-03-07","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent report of March 6 court approval and proposed creditor consideration.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:coinflex:axios","title":"CoinFLEX wants Roger Ver to pay them back","url":"https://www.axios.com/2022/06/28/coinflex-roger-ver-to-pay-them-back","publisher":"Axios","published_at":"2022-06-28","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Contemporaneous account presenting both CoinFLEX’s claim and Roger Ver’s denial.","direct_http_status":403,"access_method":"browser_rendered_page"},{"id":"source:coinflex:coindesk-rvusd","title":"CoinFLEX to launch a $47M recovery token","url":"https://www.coindesk.com/business/2022/06/27/coinflex-to-launch-a-47m-recovery-token-to-solve-withdrawal-issues","publisher":"CoinDesk","published_at":"2022-06-27","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent report on the initial rvUSD proposal and withdrawal halt.","direct_http_status":200,"access_method":"direct_http"},{"id":"source:coinflex:theblock-opnx","title":"Crypto derivatives exchange OPNX to shut down","url":"https://www.theblock.co/post/275695/crypto-derivatives-exchange-opnx-to-shut-down-in-february","publisher":"The Block","published_at":"2024-02-01","accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Independent OPNX closure report; used only as successor-context evidence.","direct_http_status":403,"access_method":"browser_rendered_page"}],"claims":[{"id":"claim:coinflex:status","field_path":"status.operating_state","assertion":"CoinFLEX trading ceased by October 31, 2023 and the brand remains tied to restructuring, recovery rights and litigation rather than an operating exchange.","value":"closed_restructured_with_disputed_recoveries","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:wipo","source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"WIPO decision, court order and restructuring report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:outcome","field_path":"outcome.label","assertion":"CoinFLEX failed after one concentrated counterparty position created a withdrawal shortfall, then converted creditor balances into a mixture of claims, tokens and equity.","value":"failed_after_concentrated_counterparty_exposure_and_restructuring","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:axios","source:coinflex:coindesk-rvusd","source:coinflex:decrypt-plan"],"evidence_locator":"Court-filed reorganization terms and independent contemporaneous coverage.","support_direction":"supports","note":"Analyst lifecycle classification; it is not a token or investment recommendation.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"CoinFLEX operated a custodial derivatives venue.","value":"CoinFLEX operated a custodial derivatives venue.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:wipo"],"evidence_locator":"Court and WIPO business descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"FLEX, flexUSD and rvUSD represented different products and rights.","value":"FLEX, flexUSD and rvUSD represented different products and rights.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:coindesk-rvusd"],"evidence_locator":"Reorganization terms and recovery-token report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body","assertion":"Trading ceased by October 31, 2023.","value":"Trading ceased by October 31, 2023.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:wipo"],"evidence_locator":"WIPO factual chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"CoinFLEX halted withdrawals after a large negative counterparty position.","value":"CoinFLEX halted withdrawals after a large negative counterparty position.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios","source:coinflex:coindesk-rvusd"],"evidence_locator":"Court and contemporaneous chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"CoinFLEX claimed $84 million from Roger Ver, who disputed the debt.","value":"CoinFLEX claimed $84 million from Roger Ver, who disputed the debt.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios"],"evidence_locator":"Company claim and counterparty denial.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:what_happened:3","field_path":"analysis.sections.what_happened.body","assertion":"The restructuring proposed dollarization, creditor equity and recovery rights.","value":"The restructuring proposed dollarization, creditor equity and recovery rights.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"Court-filed terms and approval report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"One customer exposure created the stated balance-sheet hole.","value":"One customer exposure created the stated balance-sheet hole.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles"],"evidence_locator":"Court’s summary of the company’s evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"The alleged debt remained disputed rather than adjudicated in the reviewed record.","value":"The alleged debt remained disputed rather than adjudicated in the reviewed record.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:coinflex:axios","source:coinflex:seychelles"],"evidence_locator":"Counterparty denial and plan claim.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body","assertion":"Recovery tokens transferred rather than removed recovery risk.","value":"Recovery tokens transferred rather than removed recovery risk.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:coindesk-rvusd"],"evidence_locator":"Analyst causal inference.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"CoinFLEX used special margin treatment for the large counterparty.","value":"CoinFLEX used special margin treatment for the large counterparty.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios"],"evidence_locator":"Court and contemporaneous accounts.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"The plan used dollarization, equity and recovery rights instead of cash-only repayment.","value":"The plan used dollarization, equity and recovery rights instead of cash-only repayment.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"Restructuring terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body","assertion":"The legal connection between CoinFLEX and OPNX remains disputed.","value":"The legal connection between CoinFLEX and OPNX remains disputed.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:coinflex:hong-kong","source:coinflex:theblock-opnx"],"evidence_locator":"Pleadings and later closure context.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"CoinFLEX controlled margin and withdrawals on a custodial derivatives platform.","value":"CoinFLEX controlled margin and withdrawals on a custodial derivatives platform.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:coindesk-rvusd"],"evidence_locator":"Court and market descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"A special arrangement allegedly prevented normal liquidation of the disputed position.","value":"A special arrangement allegedly prevented normal liquidation of the disputed position.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios"],"evidence_locator":"Court-filed company explanation and independent report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:operating_model:3","field_path":"analysis.sections.operating_model.body","assertion":"Restructuring converted balances into multiple creditor instruments.","value":"Restructuring converted balances into multiple creditor instruments.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"Plan terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"FLEX, flexUSD, rvUSD and equity carried distinct rights.","value":"FLEX, flexUSD, rvUSD and equity carried distinct rights.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"Court-filed restructuring categories.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"rvUSD redemption depended on successful recovery of liquid assets from Roger Ver.","value":"rvUSD redemption depended on successful recovery of liquid assets from Roger Ver.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles"],"evidence_locator":"Proposed ring-fenced SPV terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body","assertion":"OPNX’s OX token is separate from CoinFLEX recovery instruments.","value":"OPNX’s OX token is separate from CoinFLEX recovery instruments.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:theblock-opnx","source:coinflex:hong-kong"],"evidence_locator":"Successor-context and pleaded entity separation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"Concentration limits and automatic liquidation address the documented failure mode.","value":"Concentration limits and automatic liquidation address the documented failure mode.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles"],"evidence_locator":"Analyst counterfactual.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Simpler creditor consideration could have reduced valuation complexity.","value":"Simpler creditor consideration could have reduced valuation complexity.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"Analyst counterfactual.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body","assertion":"Whether outside capital or liquidation would have improved recovery is unknown.","value":"Whether outside capital or liquidation would have improved recovery is unknown.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:coinflex:seychelles"],"evidence_locator":"No completed alternative valuation is published.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The $84 million figure is a disputed company claim, not an adjudicated judgment.","value":"The $84 million figure is a disputed company claim, not an adjudicated judgment.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios"],"evidence_locator":"Legal-status boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"Final creditor value depends on several illiquid or contingent instruments.","value":"Final creditor value depends on several illiquid or contingent instruments.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:decrypt-plan"],"evidence_locator":"Plan consideration.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body","assertion":"The reviewed OPNX asset-transfer claims remain allegations.","value":"The reviewed OPNX asset-transfer claims remain allegations.","as_of":"2026-08-03","confidence":"high","kind":"unknown","source_ids":["source:coinflex:hong-kong"],"evidence_locator":"Procedural summary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body","assertion":"CoinFLEX stopped withdrawals in June 2022.","value":"CoinFLEX stopped withdrawals in June 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios"],"evidence_locator":"Court and independent chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body","assertion":"The restructuring received court approval in March 2023.","value":"The restructuring received court approval in March 2023.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:decrypt-plan"],"evidence_locator":"Approval report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body","assertion":"CoinFLEX trading ceased October 31, 2023.","value":"CoinFLEX trading ceased October 31, 2023.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:coinflex:wipo"],"evidence_locator":"WIPO decision chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Cash recovery and distributions are the decisive remaining signals.","value":"Cash recovery and distributions are the decisive remaining signals.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles"],"evidence_locator":"Recovery-vehicle design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body","assertion":"Token prices do not measure creditor distributions across mixed instruments.","value":"Token prices do not measure creditor distributions across mixed instruments.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:seychelles","source:coinflex:theblock-opnx"],"evidence_locator":"Analyst metric boundary.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body","assertion":"No reviewed source supports a CoinFLEX relaunch.","value":"No reviewed source supports a CoinFLEX relaunch.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:coinflex:wipo","source:coinflex:theblock-opnx"],"evidence_locator":"Trading cessation and successor closure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:metric:company-claimed-counterparty-debt","field_path":"metrics[metric:coinflex:company-claimed-counterparty-debt:2022-08-17].value","assertion":"CoinFLEX-claimed counterparty debt assigned to recovery rights was 84000000 USD for the stated scope and date.","value":84000000,"as_of":"2022-08-17","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios"],"evidence_locator":"Source observation checked at 2026-08-03T22:00:00Z.","support_direction":"supports","note":"A dated observation is not automatically comparable with a different entity, scope, or accounting definition.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:event:withdrawal-halt","field_path":"events[event:coinflex:withdrawal-halt]","assertion":"CoinFLEX halted withdrawals after a large counterparty position produced a claimed shortfall.","value":"2022-06-23","as_of":"2022-06-23","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles","source:coinflex:axios","source:coinflex:coindesk-rvusd"],"evidence_locator":"Court and contemporaneous reports.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:event:interim-reorganization","field_path":"events[event:coinflex:interim-reorganization]","assertion":"The Seychelles court granted interim approval for the proposed reorganization process.","value":"2022-08-17","as_of":"2022-08-17","confidence":"high","kind":"fact","source_ids":["source:coinflex:seychelles"],"evidence_locator":"Court order.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:event:plan-approved","field_path":"events[event:coinflex:plan-approved]","assertion":"The Seychelles court approved the restructuring plan.","value":"2023-03-06","as_of":"2023-03-06","confidence":"high","kind":"fact","source_ids":["source:coinflex:decrypt-plan"],"evidence_locator":"Independent report quoting the operator.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:coinflex:event:trading-ceased","field_path":"events[event:coinflex:trading-ceased]","assertion":"CoinFLEX trading officially ceased.","value":"2023-10-31","as_of":"2023-10-31","confidence":"high","kind":"fact","source_ids":["source:coinflex:wipo"],"evidence_locator":"WIPO decision chronology.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:00:00Z","next_review_at":"2026-08-10T22:00:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["Final counterparty recovery","Final creditor recovery percentage","Final intellectual-property ownership","Final estate and litigation closure"]},"extensions":{"legacy_origin":"dead_exchanges","identity_boundary":"CoinFLEX the exchange, Liquidity Technologies Ltd. the Seychelles company, the restructuring creditor pool, the rvUSD recovery vehicle, FLEX, flexUSD, and OPNX are separate subjects. The $84 million Roger Ver amount is CoinFLEX’s disputed claim reflected in a court-filed plan, not an adjudicated debt finding. OPNX’s later operation and closure do not prove that it legally succeeded CoinFLEX.","methodology_notes":["Freshness records source assembly, not human approval; every claim remains pending review.","Legal entities, venue brands, parent companies, recovery estates, custody liabilities and tokens are kept separate.","FLEX, flexUSD, rvUSD and equity represent different rights and must never be collapsed into one token recovery figure.","Hong Kong pleadings about OPNX asset transfers are allegations; this profile does not state them as adjudicated misconduct."],"explicit_unknowns":["Amount actually recovered on the disputed counterparty claim","Realized creditor value from equity, FLEX and rvUSD","Final ownership and disposition of CoinFLEX technology and domains","Status and cost of remaining restructuring and litigation"]}}', '{"kind":"cex","slug":"coinflex","lifecycle":"dead","operating_model":"Closed custodial derivatives exchange whose dollarized creditor claims received mixed equity, token and disputed-recovery rights.","product_cohort":"centralized_derivatives_exchange","custody_model":"custodial","primary_chain":null,"chains":[],"token_status":"launched","token_symbol":"FLEX","token_launch_date":"2019-07-01","token_launch_timing":"post_product","token_strategy":"venue_utility_separate_from_flexusd_and_rvusd_recovery_rights","token_source_url":"https://seylii.org/akn/sc/judgment/scsc/2022/718/eng%402022-08-17/source.pdf","metric_type":"customer_shortfall","metric_unit":"usd","metric_window":"disputed_company_claim","metric_as_of":"2022-08-17","metric_observed_at":"2026-08-03T22:00:00Z","comparability_key":"cex|centralized_derivatives_exchange|customer_shortfall|usd|disputed_company_claim","evidence":{"canonical_profile":true,"claims_pending_human_review":true,"identity_boundary":"CoinFLEX the exchange, Liquidity Technologies Ltd. the Seychelles company, the restructuring creditor pool, the rvUSD recovery vehicle, FLEX, flexUSD, and OPNX are separate subjects. The $84 million Roger Ver amount is CoinFLEX’s disputed claim reflected in a court-filed plan, not an adjudicated debt finding. OPNX’s later operation and closure do not prove that it legally succeeded CoinFLEX.","source_count":7},"quality_label":"verified","quality_issues":[],"lifecycle_evidence_date":"2026-08-03","last_verified_at":"2026-08-03","next_review_at":"2026-08-10","freshness_status":"current","updated_at":"2026-08-03"}');

INSERT INTO _cex_wave_f_profiles_0101 (
  target_table, slug, canonical_profile, feature
) VALUES ('mid_exchanges', 'xeggex', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"cex:xeggex","type":"cex","slug":"xeggex","name":"XeggeX","aliases":["XeggeX Exchange"]},"classification":{"subtype":"small-asset custodial spot exchange with failed 2025 platform and unverified 2026 brand return","tags":["custodial","spot","security-incident","data-loss","identity-risk","website-online","exchange-token"],"chains":[],"jurisdictions":["unknown"]},"status":{"operating_state":"website_online_operator_continuity_unverified","as_of":"2026-08-03","claim_ids":["claim:xeggex:status"]},"outcome":{"label":"historical_platform_failure_with_unverified_brand_return","as_of":"2026-08-03","rule_id":"exchange-lifecycle-v1","confidence":"medium","claim_ids":["claim:xeggex:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"XeggeX was a custodial exchange focused on many smaller crypto assets and used internal accounts for deposits, trading and withdrawals. A severe February 2025 incident took the platform offline and damaged its data. A website with the same brand is live again in 2026 and advertises trading and proof of reserves. The current terms do not name the legal operator, so Chaindump treats the old failed platform and the present site as unverified counterparts, not one proven continuous business.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:what_it_is:1","claim:xeggex:section:what_it_is:2","claim:xeggex:section:what_it_is:3"]},"what_happened":{"body":"On February 3, 2025 XeggeX reported a security breach and data loss after an administrator device and communication accounts were compromised. The archived statement said database collections were deleted and restoration was attempted. Pactus later reported asset movements and publicly raised exit-scam concerns, but that was its assessment rather than an official finding. The old service did not transparently recover. A new-looking site later appeared under the same domain without a published liability-assumption record.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:what_happened:1","claim:xeggex:section:what_happened:2","claim:xeggex:section:what_happened:3"]},"why_this_outcome":{"body":"The documented technical failure combined privileged access, communications and critical data around an administrator device. Once that access was compromised, databases were taken offline or deleted and users lost reliable account access. That is both a security-architecture and governance failure: an exchange should not depend on one poorly isolated control path. The later lack of a named operator, audited incident account and liability reconciliation prevented trust from being rebuilt even though the domain returned.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:why_this_outcome:1","claim:xeggex:section:why_this_outcome:2","claim:xeggex:section:why_this_outcome:3"]},"strategic_choices":{"body":"The historical exchange chose to list a long tail of assets and run customer access through a centralized platform with opaque legal and operational ownership. Its incident account indicates sensitive administrative authority was concentrated around one device. The current site chose to publish a Merkle-style proof page and communication checker, which addresses visible trust concerns, but it did not publish the legal entity, independent audit, incident reconciliation or assumption of old balances needed to prove a genuine recovery.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:strategic_choices:1","claim:xeggex:section:strategic_choices:2","claim:xeggex:section:strategic_choices:3"]},"operating_model":{"body":"Customers deposited digital assets, traded them on an internal platform and depended on XeggeX to maintain account data and authorize withdrawals. That model makes database integrity, wallet control and legal accountability inseparable from customer access. The current terms describe the platform as a facilitator and reserve broad suspension powers, while the proof page shows operator-produced balances. Without a named contracting company and independent liability audit, users cannot verify who owes them assets or whether all liabilities are included.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:operating_model:1","claim:xeggex:section:operating_model:2","claim:xeggex:section:operating_model:3"]},"token_and_value_capture":{"body":"Xpense, symbol XPE, was presented as the native token of the historical XeggeX exchange and received an independent Poloniex listing. Its claimed utility included venue-related functions, so value depended on continued platform use. The current XeggeX site does not provide a clear, legally binding statement that old XPE rights continue, were migrated or were redeemed. The presence of an old whitepaper or current token references is therefore history, not proof of present holder rights.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:token_and_value_capture:1","claim:xeggex:section:token_and_value_capture:2","claim:xeggex:section:token_and_value_capture:3"]},"counterfactual":{"body":"Hardware-backed privileged access, separation of duties, offline database backups and tested disaster recovery could have limited the 2025 blast radius. A public incident report and independently reconciled customer ledger could have made recovery credible. For the current site, naming the legal operator, proving ownership continuity and auditing both assets and liabilities would materially change the risk call. None of those safeguards can be inferred from a live domain or a self-published Merkle page alone.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:counterfactual:1","claim:xeggex:section:counterfactual:2","claim:xeggex:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The largest current risk is identity: users cannot tell from the terms which legal entity operates the site or whether it owes anything to customers of the failed platform. The reserve page may show selected balances but does not establish an independent audit, ownership continuity or complete liabilities. Historical loss estimates of $80 million and 12,000 users, plus a June 2025 bankruptcy claim, lack the primary court or administrator record required for publication and are intentionally excluded.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:risks_and_unknowns:1","claim:xeggex:section:risks_and_unknowns:2","claim:xeggex:section:risks_and_unknowns:3"]},"lifecycle":{"body":"XeggeX operated from roughly 2021, launched XPE and built a niche exchange for smaller assets. The February 2025 compromise caused a platform and data failure from which the old service did not transparently recover. In 2026 the domain again presents an exchange interface, proof page and updated terms. Because operator identity, customer-liability continuity and recovery records are missing, the lifecycle is not “reopened.” It is a failed historical platform followed by an unverified brand return.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:lifecycle:1","claim:xeggex:section:lifecycle:2","claim:xeggex:section:lifecycle:3"]},"outlook_and_watch":{"body":"Watch for a named legal operator and jurisdiction, signed proof that it controls the historic company or assets, an independent reserve-and-liability audit, and a plan for old customer balances and XPE. Verified documentation on those points could move the current site into a normal operating review. Absent that evidence, a functioning interface should not override the 2025 failure record. Any formal insolvency claim also needs a court or administrator document before publication.","as_of":"2026-08-03","claim_ids":["claim:xeggex:section:outlook_and_watch:1","claim:xeggex:section:outlook_and_watch:2","claim:xeggex:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:xeggex:xpe-listing","type":"token","date":"2023-10-03","description":"Poloniex announced a listing of XPE and identified it as the XeggeX token.","claim_ids":["claim:xeggex:event:xpe-listing"]},{"id":"event:xeggex:security-incident","type":"security","date":"2025-02-03","description":"XeggeX reported a security breach, login shutdown and data loss.","claim_ids":["claim:xeggex:event:security-incident"]},{"id":"event:xeggex:pactus-warning","type":"ecosystem_warning","date":"2025-02-10","description":"Pactus reported asset movements and raised concerns about a possible exit scam.","claim_ids":["claim:xeggex:event:pactus-warning"]},{"id":"event:xeggex:current-site-observed","type":"website_return","date":"2026-08-03","description":"A XeggeX-branded trading site and current terms were online, with operator continuity unverified.","claim_ids":["claim:xeggex:event:current-site-observed"]}],"sources":[{"id":"source:xeggex:terms","title":"XeggeX terms and conditions","url":"https://xeggex.com/legal/terms","publisher":"XeggeX","published_at":null,"accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Current platform terms describing digital-asset trading but not naming a contracting legal entity.","direct_http_status":0,"access_method":"indexed_browser_snapshot"},{"id":"source:xeggex:reserves","title":"XeggeX proof of liabilities and reserves","url":"https://xeggex.com/provereserves","publisher":"XeggeX","published_at":null,"accessed_at":"2026-08-03T22:00:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","resolving":true,"reachable":true,"checked_at":"2026-08-03T22:00:00Z","content_hash":null,"evidence_locator":"Current operator-produced Merkle-liability and reserve page, stated to refresh every six hours.","direct_http_status":0,"access_method":"indexed_browser_snapshot"},{"id":"source:xeggex:homepage","title":"XeggeX cryptocurrency exchange","url":"https://www.xeggex.com/","publisher":"XeggeX","publ